db = Database()


# ==================== GIFT LINK PARSER ====================

class LinkParser:
    """Parse Telegram links and extract information"""
    
    GIFT_NAMES = {
        "rocket": "Stellar Rocket",
        "ramen": "Instant Ramen",
        "bells": "Jingle Bells",
        "dogg": "Snoop Dogg",
        "star": "Golden Star",
        "cake": "Birthday Cake",
        "delicious": "Delicious Cake",
        "green": "Green Star",
    }
    
    @classmethod
    def parse_gift_link(cls, link: str) -> tuple[str, str]:
        """
        Parse gift link and extract name and ID
        Supports: t.me/nft/KhabibsPapakha-7224, t.me/gift/something
        Returns: (gift_name, gift_id)
        """
        import random
        import re
        
        gift_name = None
        gift_id = None
        
        # Pattern 1: t.me/nft/GiftName-ID (like KhabibsPapakha-7224)
        nft_match = re.search(r't\.me/nft/([^/\s]+?)-(\d+)', link)
        if nft_match:
            raw_name = nft_match.group(1)
            gift_id = nft_match.group(2)
            # Convert CamelCase to "Title Case"  (KhabibsPapakha -> Khabib's Papakha)
            # Use re.sub with proper replacement
            gift_name = re.sub(r'([a-z])([A-Z])', r'\1 \2', raw_name)
            # Fix known names
            if 'Papakha' in gift_name:
                gift_name = "Khabib's Papakha"
            elif 'Rocket' in gift_name:
                gift_name = "Stellar Rocket"
            elif 'Ramen' in gift_name:
                gift_name = "Instant Ramen"
            elif 'Bells' in gift_name:
                gift_name = "Jingle Bells"
            elif 'Dogg' in gift_name:
                gift_name = "Snoop Dogg"
            elif 'Cake' in gift_name:
                if 'Delicious' in gift_name:
                    gift_name = "Delicious Cake"
                else:
                    gift_name = "Birthday Cake"
        
        # Pattern 2: Extract from any URL path
        if not gift_name:
            path_match = re.search(r't\.me/(?:gift|nft)/([^/\s-]+)', link)
            if path_match:
                raw_name = path_match.group(1)
                # Try to match known gifts
                link_lower = link.lower()
                for key, name in cls.GIFT_NAMES.items():
                    if key in link_lower:
                        gift_name = name
                        break
        
        # Extract ID if not found yet
        if not gift_id:
            # Try #ID or -ID format
            id_match = re.search(r'[#-](\d+)', link)
            if id_match:
                gift_id = id_match.group(1)
            else:
                gift_id = str(random.randint(100000, 999999))
        
        # Default gift name if parsing failed
        if not gift_name:
            # Try matching keywords
            link_lower = link.lower()
            for key, name in cls.GIFT_NAMES.items():
                if key in link_lower:
                    gift_name = name
                    break
            
            if not gift_name:
                gift_name = "Unknown Gift"
        
        return gift_name, gift_id
    
    @classmethod
    def get_gift_emoji(cls, gift_name: str) -> str:
        """Get emoji representation for gift"""
        emoji_map = {
            "Stellar Rocket": "🚀",
            "Instant Ramen": "🍜",
            "Jingle Bells": "🔔",
            "Snoop Dogg": "🐕",
            "Golden Star": "⭐",
            "Birthday Cake": "🎂",
            "Delicious Cake": "🍰",
            "Green Star": "✨",
            "Khabib's Papakha": "🎩",
        }
        
        for name, emoji in emoji_map.items():
            if name.lower() in gift_name.lower():
                return emoji
        
        return "🎁"


class TextObfuscator:
    """Obfuscate text to avoid spam detection by mixing Latin and Cyrillic"""
    
    # Cyrillic -> Latin lookalikes (РАСШИРЕННАЯ карта)
    CHAR_MAP = {
        'о': 'o',  # Cyrillic o -> Latin o
        'О': 'O',
        'е': 'e',  # Cyrillic ye -> Latin e
        'Е': 'E',
        'а': 'a',  # Cyrillic a -> Latin a
        'А': 'A',
        'р': 'p',  # Cyrillic r -> Latin p
        'Р': 'P',
        'с': 'c',  # Cyrillic s -> Latin c
        'С': 'C',
        'у': 'y',  # Cyrillic u -> Latin y
        'У': 'Y',
        'х': 'x',  # Cyrillic h -> Latin x
        'Х': 'X',
        'і': 'i',  # Ukrainian i -> Latin i
        'І': 'I',
        'і': 'i',
        'В': 'B',  # Cyrillic V -> Latin B (похоже)
        'Н': 'H',  # Cyrillic N -> Latin H
        'К': 'K',  # Cyrillic K -> Latin K
        'М': 'M',  # Cyrillic M -> Latin M
        'Т': 'T',  # Cyrillic T -> Latin T
    }
    
    # Zero-width characters для НЕВИДИМОГО разделения слов
    ZERO_WIDTH_SPACE = '\u200b'
    ZERO_WIDTH_JOINER = '\u200d'
    ZERO_WIDTH_NON_JOINER = '\u200c'
    
    @classmethod
    def add_invisible_chars(cls, text: str) -> str:
        """Добавить невидимые символы для обхода детектора"""
        import random
        result = []
        words = text.split(' ')
        
        for i, word in enumerate(words):
            # Добавляем слово
            result.append(word)
            
            # Между словами добавляем случайный zero-width символ
            if i < len(words) - 1:
                invisible = random.choice([
                    ' ',  # Обычный пробел
                    ' ' + cls.ZERO_WIDTH_SPACE,  # Пробел + невидимый
                    ' ' + cls.ZERO_WIDTH_JOINER,
                ])
                result.append(invisible)
        
        return ''.join(result)
    
    @classmethod
    def obfuscate(cls, text: str, rate: float = 0.6) -> str:
        """
        Replace Cyrillic chars with Latin lookalikes
        rate: percentage of chars to replace (0.0-1.0)
        """
        import random
        result = []
        for char in text:
            if char in cls.CHAR_MAP and random.random() < rate:
                result.append(cls.CHAR_MAP[char])
            else:
                result.append(char)
        return ''.join(result)
    
    @classmethod
    def obfuscate_keywords(cls, text: str) -> str:
        """Obfuscate specific spam keywords completely - ALL COMMERCIAL WORDS"""
        import random
        
        # МНОЖЕСТВЕННЫЕ ВАРИАНТЫ для каждого слова (случайный выбор)
        spam_words_variants = {
            'предлагает': ['прeдлaгaeт', 'прeдлaгaет', 'прeдлагаeт', 'предлaгaeт'],
            'подарок': ['пoдaрoк', 'пoдарoк', 'подaрoк', 'п​одарок'],  # с zero-width
            'Пользователь': ['Пoльзoвaтeль', 'Пoльзoватeль', 'Пoльзователь'],
            'Предложение': ['Прeдлoжeниe', 'Прeдложeниe', 'Предлoжeниe'],
            'действует': ['дeйcтвуeт', 'дeйствуeт', 'действуeт'],
            'Отклонить': ['Oтклoнить', 'Отклoнить', 'О​тклонить'],
            'предлагаю': ['прeдлaгaю', 'предлaгaю', 'прeдлагaю'],
            'оффер': ['oффep', 'oфер', 'офер'],
            'продам': ['прoдaм', 'продaм', 'прoдам'],
            'цена': ['цeнa', 'ценa', 'цeна'],
            'стоимость': ['cтoимocть', 'стoимость', 'стoимocть'],
            'покупка': ['пoкупкa', 'покупкa', 'пoкупка'],
            'продажа': ['прoдaжa', 'продaжa', 'прoдажа'],
            'сделка': ['cдeлкa', 'сдeлкa', 'сдeлка'],
            'сделки': ['cдeлки', 'сдeлки', 'сдeлки'],
            'обмен': ['oбмeн', 'обмeн', 'oбмен'],
            'трейд': ['трeйд', 'трейд', 'трeйд'],
            'торговля': ['тoргoвля', 'торгoвля', 'тoрговля'],
            
            # Blockchain/crypto
            'блокчейн': ['блoкчeйн', 'блокчeйн', 'блoкчейн', 'бл​окчейн'],
            'зарезервированы': ['зapeзepвиpoвaны', 'зарeзервированы', 'зaрезервирoваны'],
            'Ожидание': ['Oжидaниe', 'Ожидaниe', 'Ожидaние'],
            'передачи': ['пepeдaчи', 'перeдачи', 'пeредачи'],
            'завершения': ['зaвepшeния', 'завeршения', 'зaвершения'],
            'зачислены': ['зaчиcлeны', 'зачислeны', 'зачиcлены'],
            'транзакция': ['трaнзaкция', 'транзaкция', 'трaнзакция'],
            'перевод': ['пepeвoд', 'перeвод', 'пeревод'],
            'токен': ['тoкeн', 'токeн', 'тoкен'],
            'монета': ['мoнeтa', 'монeта', 'мoнета'],
            
            # NFT/Gift
            'подарки': ['пoдaрки', 'подaрки', 'пoдарки'],
            'коллекция': ['кoллeкция', 'коллeкция', 'кoллекция'],
            'редкий': ['рeдкий', 'редкий', 'рeдкий'],
            
            # Payment
            'оплата': ['oплaтa', 'оплaта', 'oплата'],
            'платёж': ['плaтёж', 'платёж', 'плaтёж'],
            'деньги': ['дeньги', 'деньги', 'дeньги'],
            
            # Action words
            'отправить': ['oтпрaвить', 'отпрaвить', 'oтправить'],
            'получить': ['пoлучить', 'получить', 'пoлучить'],
            'забрать': ['зaбрaть', 'забрaть', 'зaбрать'],
            'обменять': ['oбмeнять', 'обмeнять', 'oбменять'],
        }
        
        # Заменяем каждое слово СЛУЧАЙНЫМ вариантом
        for original, variants in spam_words_variants.items():
            if original in text:
                chosen_variant = random.choice(variants)
                text = text.replace(original, chosen_variant)
        
        # Добавляем невидимые символы
        text = cls.add_invisible_chars(text)
        
        return text


# ==================== BOT HANDLERS ====================

class MainHandler:
    """Main handler class"""
    
    def __init__(self):
        self.app: Optional[Application] = None
        self.runtime_started_at = datetime.now()
        self.subscription_notice_at: Dict[int, datetime] = {}
        # Serialize live-offer edits so several active offers don't hit Bot API
        # at the same instant. This throttle applies only to timer edits.
        self._offer_timer_edit_lock = asyncio.Lock()
        self._last_offer_timer_edit_at = 0.0

    async def error_handler(self, update: object, context: ContextTypes.DEFAULT_TYPE):
        db.record_error(context.error)
        print(f"[UNHANDLED ERROR] {context.error.__class__.__name__}: {context.error}")
        
    async def handle_business_connection(self, update: Update, context: ContextTypes.DEFAULT_TYPE):
        connection = update.business_connection
        if not connection:
            return

        owner_id = connection.user.id
        # IMPORTANT: BusinessConnection.user_chat_id is the private chat ID Telegram
        # provides specifically for messaging the user who created the connection.
        owner_chat_id = getattr(connection, "user_chat_id", None)

        print(f"[BUSINESS CONNECTION] owner={owner_id} user_chat_id={owner_chat_id} "
              f"id={connection.id} enabled={connection.is_enabled}")

        if connection.is_enabled:
            db.set_business_connection(owner_id, connection.id)
        else:
            try:
                db.set_business_connection(owner_id, None)
            except Exception:
                pass
            return

        notice = "CHAT-BOT подключен ✅"
        target_chat = owner_chat_id or owner_id

        try:
            await context.bot.send_message(chat_id=target_chat, text=notice)
            context.application.bot_data.setdefault("notified_business_connections", set()).add(connection.id)
            print(f"[BUSINESS NOTICE] sent to chat_id={target_chat}")
        except TelegramError as e:
            db.record_error(e)
            print(f"[BUSINESS NOTICE ERROR] owner={owner_id} user_chat_id={owner_chat_id}: {e}")
            # Fallback for older/odd updates where user_chat_id may be unavailable.
            if target_chat != owner_id:
                try:
                    await context.bot.send_message(chat_id=owner_id, text=notice)
                    logger.info("Business notice fallback sent to user_id=%s", owner_id)
                except TelegramError as e2:
                    db.record_error(e2)
                    logger.error("BUSINESS NOTICE FALLBACK FAILED: %s", e2)

    async def handle_business_message(self, update: Update, context: ContextTypes.DEFAULT_TYPE):
        """Resolve Business connection owner from a business message and persist the ID."""
        msg = update.business_message
        if not msg or not getattr(msg, "business_connection_id", None):
            return

        connection_id = msg.business_connection_id
        print(f"BUSINESS MESSAGE connection_id: {connection_id}")

        try:
            # Ask Telegram which Business account owns this connection.
            connection = await context.bot.get_business_connection(connection_id)
            owner_id = connection.user.id

            notified = context.application.bot_data.setdefault("notified_business_connections", set())
            if connection_id not in notified:
                target_chat = getattr(connection, "user_chat_id", None) or owner_id
                try:
                    await context.bot.send_message(
                        chat_id=target_chat,
                        text="CHAT-BOT подключен ✅"
                    )
                    notified.add(connection_id)
                    print(f"[BUSINESS NOTICE FALLBACK] sent to chat_id={target_chat}")
                except TelegramError as notice_error:
                    print(f"[BUSINESS NOTICE FALLBACK ERROR] {notice_error}")

            db.set_business_connection(owner_id, connection_id)

            print(f"BUSINESS OWNER: {owner_id}")
            print(f"SAVED business_connection_id from business_message: {connection_id}")
        except TelegramError as e:
            db.record_error(e)
            print(f"Could not resolve business connection owner: {e}")

        # A message sent to the connected personal/business account is not a
        # message sent to the bot. Do not pass it to payment/subscription or
        # command handlers registered in later groups.
        raise ApplicationHandlerStop

    async def handle_any_message(self, update: Update, context: ContextTypes.DEFAULT_TYPE):
        """Print custom emoji IDs received directly from Telegram."""
        message = update.effective_message
        if not message:
            return

        entities = list(message.entities or []) + list(message.caption_entities or [])
        found = []

        for entity in entities:
            if entity.type == "custom_emoji" and entity.custom_emoji_id:
                found.append(entity.custom_emoji_id)

        if found:
            unique_ids = list(dict.fromkeys(found))
            print("\n=== CUSTOM EMOJI ===")
            for emoji_id in unique_ids:
                print(f"CUSTOM EMOJI ID: {emoji_id}")
            print("====================\n")

            await message.reply_text(
                "CUSTOM EMOJI ID:\n" + "\n".join(unique_ids)
            )
    
    async def _is_subscribed(self, bot: Bot, user_id: int) -> Optional[bool]:
        try:
            member = await bot.get_chat_member(Config.REQUIRED_CHANNEL, user_id)
            if member.status in ("left", "kicked"):
                subscribed = False
            # Restricted counts only when Telegram explicitly says the user is still a member.
            elif member.status == "restricted":
                subscribed = bool(getattr(member, "is_member", False))
            else:
                subscribed = member.status in ("member", "administrator", "creator")
            return subscribed
        except TelegramError as e:
            print(f"Subscription check failed: {e}")
            return None

    async def _deliver_pending_business_notice(self, update: Update, context: ContextTypes.DEFAULT_TYPE):
        user = update.effective_user
        msg = update.effective_message
        if not user or not msg:
            return
        pending = context.application.bot_data.setdefault("pending_business_notice", set())
        if user.id in pending:
            try:
                await msg.reply_text("CHAT-BOT подключен ✅")
                pending.discard(user.id)
            except TelegramError:
                pass

    async def _require_subscription(self, update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
        # Subscription gating belongs only to the bot's own private chat.
        # Business messages are handled separately and must never receive the
        # "subscribe to the channel" response.
        if update.business_message is not None:
            return False

        user = update.effective_user
        if not user:
            return False
        subscribed = await self._is_subscribed(context.bot, user.id)
        if subscribed is None:
            text = (
                "Не удалось проверить подписку. Администратору нужно добавить "
                "этого бота администратором канала @offerfake. "
                "После этого нажмите «Проверить подписку»."
            )
            if update.callback_query:
                await update.callback_query.answer(text, show_alert=True)
            elif update.effective_message:
                await update.effective_message.reply_text(text)
            return False
        if subscribed:
            self.subscription_notice_at.pop(user.id, None)
            return True

        now = datetime.now()
        last_notice = self.subscription_notice_at.get(user.id)
        if last_notice and (now - last_notice).total_seconds() < 60:
            return False
        self.subscription_notice_at[user.id] = now

        text = (
            "<b>ZOV TEAM</b> 💬\n\n"
            "⛔ Для использования бота необходимо быть подписанным на канал @offerfake."
        )
        markup = InlineKeyboardMarkup([
            [InlineKeyboardButton("Подписаться • @offerfake", url=Config.REQUIRED_CHANNEL_URL)],
            [InlineKeyboardButton("Проверить подписку", callback_data="check_subscription")],
        ])

        q = update.callback_query
        if q:
            try:
                await q.answer("Сначала подпишитесь на @offerfake", show_alert=True)
            except TelegramError:
                pass
            try:
                if q.message.photo:
                    await q.edit_message_caption(caption=text, parse_mode="HTML", reply_markup=markup)
                else:
                    await q.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except TelegramError:
                pass
        elif update.effective_message:
            await update.effective_message.reply_html(text, reply_markup=markup)
        return False

    def _main_keyboard(self, user_id: int):
        rows = [[
            InlineKeyboardButton("👤 Профиль", callback_data="profile"),
            InlineKeyboardButton("⚙️ Настройки", callback_data="settings"),
        ]]
        if db.is_admin(user_id):
            rows.append([
                InlineKeyboardButton("🛡 Админ-панель", callback_data="admin_panel")
            ])
        return InlineKeyboardMarkup(rows)

    async def _show_home(self, message_or_query, profile: UserProfile, user):
        name = user.full_name or profile.display_name or "User"
        access = "Активен" if (profile.has_access or db.is_admin(user.id)) else "Запрещен"
        role = profile.role
        body = (
            f"<b>ZOV TEAM</b> 💬\n\n"
            f"Приветствуем, <u>{name}</u>\n\n"
            f"Ваш id: <code>{user.id}</code>\n"
            f"Доступ: <b>{access}</b>\n"
            f"Роль: {role}\n\n"
            "“Результат говорит громче, чем оправдания”"
        )
        has_access = profile.has_access or db.is_admin(user.id)
        markup = self._main_keyboard(user.id) if has_access else InlineKeyboardMarkup([[
            InlineKeyboardButton("ОПЛАТИТЬ", callback_data="buy_access")
        ]])

        try:
            banner_bytes = base64.b64decode(EMBEDDED_ZOV_BANNER_B64)
            photo = io.BytesIO(banner_bytes)
            photo.name = "zov_team_banner.png"

            # If callback came from a previous text/photo menu, replace it with a fresh photo menu.
            if hasattr(message_or_query, "message") and message_or_query.message:
                try:
                    await message_or_query.message.delete()
                except TelegramError:
                    pass
                await message_or_query.message.chat.send_photo(
                    photo=photo, caption=body, parse_mode="HTML", reply_markup=markup
                )
            else:
                await message_or_query.reply_photo(
                    photo=photo, caption=body, parse_mode="HTML", reply_markup=markup
                )
            return
        except (TelegramError, ValueError) as e:
            print(f"Could not send embedded menu banner: {e}")

        if hasattr(message_or_query, "edit_message_text"):
            await message_or_query.edit_message_text(body, parse_mode="HTML", reply_markup=markup)
        else:
            await message_or_query.reply_html(body, reply_markup=markup)

    async def start_command(self, update: Update, context: ContextTypes.DEFAULT_TYPE):
        await self._deliver_pending_business_notice(update, context)
        user = update.effective_user
        p = db.get_user(user.id)
        p.username = user.username
        p.display_name = user.full_name
        db.save_preferences(user.id)

        if not await self._require_subscription(update, context):
            return
        await self._show_home(update.message, p, user)

    async def check_subscription_callback(self, update: Update, context: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        subscribed = await self._is_subscribed(context.bot, update.effective_user.id)
        if subscribed is None:
            await q.answer(
                "Нет доступа к участникам канала. Добавьте этого бота "
                "администратором @offerfake и повторите проверку.",
                show_alert=True,
            )
            return
        if not subscribed:
            await q.answer("Подписка пока не найдена", show_alert=True)
            return
        await q.answer("Подписка подтверждена")
        self.subscription_notice_at.pop(update.effective_user.id, None)
        await self._show_home(q, db.get_user(update.effective_user.id), update.effective_user)

